                <p className="text-xs text-slate-400 mt-1">Recorded 01 Oct 2026 (1h 45m)</p>
                <button onClick={() => alert('Playing video...')} className="mt-3 text-xs text-violet-400 font-bold">Watch Stream →</button>
              </div>
              <div className="bg-slate-800/50 p-4 rounded-xl border border-slate-700/60">
                <p className="font-semibold text-white">Lecture 2: Variables & Data Types</p>
                <p className="text-xs text-slate-400 mt-1">Recorded 03 Oct 2026 (1h 50m)</p>
                <button onClick={() => alert('Playing video...')} className="mt-3 text-xs text-violet-400 font-bold">Watch Stream →</button>
