          )}
          {activeTab === 'notes' && (
            <div className="space-y-2">
              <div className="flex items-center justify-between p-3 bg-slate-800/40 rounded-xl">
                <span className="text-xs">Python_Fundamentals_CheatSheet.pdf</span>
                <button onClick={() => alert('Downloading file...')} className="text-xs text-emerald-400 font-bold">Download</button>
