          {activeTab === 'assignments' && (
            <div className="p-4 bg-slate-800/40 rounded-xl text-xs space-y-1">
              <p className="font-bold text-white">Assignment 3: Web Scraping Task</p>
              <p className="text-yellow-400">Due Sunday 11:59 PM</p>
            </div>
          )}
          {activeTab === 'projects' && (
            <div className="p-4 bg-slate-800/40 rounded-xl text-xs space-y-1">
              <p className="font-bold text-white">Capstone: GenAI Resume Matcher</p>
              <p className="text-slate-400">Streamlit & OpenAI integration task</p>
