function ProjectEnquiryModal({ isOpen, onClose, initialDomain = '' }) {
  const [submitted, setSubmitted] = useState(false);
  const [formData, setFormData] = useState({
    name: 'Harsha',
    mobile: '9876543210',
    email: 'harsha@example.com',
    degree: 'B.Tech',
    branch: 'Computer Science',
    domain: initialDomain || 'AI / Machine Learning',
    tech: 'Python, Django, React',
    requirement: 'Need complete source code, documentation, and PPT for final review.',
    expectedDate: '2026-11-15'
  });

  if (!isOpen) return null;

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
    setTimeout(() => {
      setSubmitted(false);
      onClose();
      alert('Requirement submitted! Our team will contact you within 2 hours.');
    }, 1000);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm overflow-y-auto">
      <div className="bg-slate-900 border border-slate-800 rounded-3xl max-w-lg w-full p-6 sm:p-8 space-y-6 relative shadow-2xl my-8">
        <button onClick={onClose} className="absolute top-6 right-6 text-slate-400 hover:text-white p-1 rounded-lg">
          <X className="w-5 h-5" />
        </button>

        <div className="space-y-1">
          <span className="text-xs font-semibold uppercase tracking-wider text-emerald-400">Academic Project Desk</span>
          <h3 className="text-2xl font-bold text-white">Project Enquiry Screen</h3>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Student Name</label>
              <input
                type="text"
                required
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Mobile</label>
              <input
                type="tel"
                required
                value={formData.mobile}
                onChange={(e) => setFormData({ ...formData, mobile: e.target.value })}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Degree</label>
              <select
                value={formData.degree}
                onChange={(e) => setFormData({ ...formData, degree: e.target.value })}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs"
              >
                <option value="B.Tech">B.Tech</option>
                <option value="M.Tech">M.Tech</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Branch</label>
              <input
                type="text"
                value={formData.branch}
                onChange={(e) => setFormData({ ...formData, branch: e.target.value })}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Project Domain</label>
              <input
                type="text"
                value={formData.domain}
                onChange={(e) => setFormData({ ...formData, domain: e.target.value })}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Preferred Technology</label>
              <input
                type="text"
                value={formData.tech}
                onChange={(e) => setFormData({ ...formData, tech: e.target.value })}
                className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Project Requirement description</label>
            <textarea
              rows="3"
              value={formData.requirement}
              onChange={(e) => setFormData({ ...formData, requirement: e.target.value })}
              className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs"
            ></textarea>
          </div>

          <div>
            <label className="block text-xs font-medium text-slate-400 uppercase mb-1">Expected Completion Date</label>
            <input
              type="date"
              value={formData.expectedDate}
              onChange={(e) => setFormData({ ...formData, expectedDate: e.target.value })}
              className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-white text-xs"
            />
          </div>

          <button
            type="submit"
            disabled={submitted}
            className="w-full py-3.5 rounded-xl bg-gradient-to-r from-violet-600 to-indigo-600 hover:from-violet-500 hover:to-indigo-500 text-white font-bold text-sm shadow-lg shadow-violet-600/30 transition flex items-center justify-center space-x-2"
          >
            {submitted ? <Check className="w-5 h-5 text-emerald-400" /> : <span>Submit Requirement</span>}
          </button>
        </form>
      </div>
    </div>
  );
}

export default function App() {
  const [activeScreen, setActiveScreen] = useState('home');

  // Booking Flow Modals
  const [slotModalOpen, setSlotModalOpen] = useState(false);
  const [studentModalOpen, setStudentModalOpen] = useState(false);
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [confirmModalOpen, setConfirmModalOpen] = useState(false);

  // Workshop Registration Modal
  const [workshopModalOpen, setWorkshopModalOpen] = useState(false);
  const [selectedWorkshop, setSelectedWorkshop] = useState(null);

  // Project Enquiry Modal
  const [projectEnquiryOpen, setProjectEnquiryOpen] = useState(false);
  const [selectedProjectDomain, setSelectedProjectDomain] = useState('');

  // Config States
  const [guidanceConfig, setGuidanceConfig] = useState({ duration: '30 Minutes', price: 49 });
  const [bookingMeta, setBookingMeta] = useState({});
  const [paymentConfig, setPaymentConfig] = useState({ fee: 29, title: 'Booking Registration Fee' });

  // Guidance Flow
  const startGuidanceBooking = (config) => {
    setGuidanceConfig(config);
    setSlotModalOpen(true);
  };

  const handleSlotSelected = (slotData) => {
    setBookingMeta((prev) => ({ ...prev, ...slotData }));
    setSlotModalOpen(false);
    setStudentModalOpen(true);
  };

  const handleStudentDetailsSubmitted = (studentData) => {
    setBookingMeta((prev) => ({ ...prev, ...studentData }));
    setStudentModalOpen(false);
    setPaymentConfig({ fee: 29, title: 'Booking Registration Fee: ₹29' });
    setPaymentModalOpen(true);
  };

  const handlePaymentSuccess = () => {
    setPaymentModalOpen(false);
    setConfirmModalOpen(true);
  };

  // Workshop Flow
  const openWorkshopRegister = (workshop) => {
    setSelectedWorkshop(workshop);
    setWorkshopModalOpen(true);
  };

  const handleWorkshopProceedToPay = ({ feeAmount, itemTitle, meta }) => {
    setBookingMeta((prev) => ({ ...prev, ...meta }));
    setWorkshopModalOpen(false);
    setPaymentConfig({ fee: feeAmount, title: itemTitle });
    setPaymentModalOpen(true);
  };

  // Course Flow
  const handleCourseEnroll = (course) => {
    setPaymentConfig({ fee: course.price, title: `Full Enrollment: ${course.title}` });
    setPaymentModalOpen(true);
  };

  // Internship Flow
  const handleApplyInternship = (internship) => {
    setPaymentConfig({ fee: 29, title: `Internship Registration Fee: ${internship.title}` });
    setPaymentModalOpen(true);
  };

  // Project Enquiry Flow
  const handleOpenProjectEnquiry = (domainOrTitle) => {
    setSelectedProjectDomain(domainOrTitle);
    setProjectEnquiryOpen(true);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col font-sans selection:bg-violet-600 selection:text-white">
      <Header setActiveScreen={setActiveScreen} />
      <Navbar activeScreen={activeScreen} setActiveScreen={setActiveScreen} />

      <main className="flex-1">
        {activeScreen === 'home' && (
          <Home
            setActiveScreen={setActiveScreen}
            onOpenGuidanceBooking={() => startGuidanceBooking({ duration: '30 Minutes', price: 49 })}
          />
        )}

        {activeScreen === 'guidance' && (
          <CareerGuidanceScreen onStartBooking={startGuidanceBooking} />
        )}

        {activeScreen === 'workshops' && (
          <WorkshopsScreen onOpenWorkshopRegister={openWorkshopRegister} />
        )}

        {activeScreen === 'courses' && (
          <Courses onEnrollCourse={handleCourseEnroll} />
        )}

        {activeScreen === 'my-courses' && (
          <MyCoursesScreen />
        )}

        {activeScreen === 'internships' && (
          <InternshipsScreen onApplyInternship={handleApplyInternship} />
        )}

        {activeScreen === 'btech-projects' && (
          <ProjectsScreen type="B.Tech" onOpenEnquiry={handleOpenProjectEnquiry} />
        )}

        {activeScreen === 'mtech-projects' && (
          <ProjectsScreen type="M.Tech" onOpenEnquiry={handleOpenProjectEnquiry} />
        )}

        {activeScreen === 'about' && (
          <About setActiveScreen={setActiveScreen} />
        )}

        {activeScreen === 'dashboard' && (
          <StudentDashboardScreen setActiveScreen={setActiveScreen} />
        )}

        {activeScreen === 'contact' && (
          <Contact />
        )}
      </main>

      <Footer setActiveScreen={setActiveScreen} />

      {/* Interactive Modals */}
      <BookSlotModal
        isOpen={slotModalOpen}
        onClose={() => setSlotModalOpen(false)}
        initialData={guidanceConfig}
        onProceed={handleSlotSelected}
      />

      <StudentDetailsModal
        isOpen={studentModalOpen}
        onClose={() => setStudentModalOpen(false)}
        onProceed={handleStudentDetailsSubmitted}
      />

      <PaymentModal
        isOpen={paymentModalOpen}
        onClose={() => setPaymentModalOpen(false)}
        feeAmount={paymentConfig.fee}
        itemTitle={paymentConfig.title}
        onPaySuccess={handlePaymentSuccess}
      />

      <ConfirmationModal
        isOpen={confirmModalOpen}
        onClose={() => setConfirmModalOpen(false)}
        bookingData={bookingMeta}
      />

      <WorkshopRegisterModal
        isOpen={workshopModalOpen}
        onClose={() => setWorkshopModalOpen(false)}
        selectedWorkshop={selectedWorkshop}
        onProceedPayment={handleWorkshopProceedToPay}
      />

      <ProjectEnquiryModal
        isOpen={projectEnquiryOpen}
        onClose={() => setProjectEnquiryOpen(false)}
        initialDomain={selectedProjectDomain}
      />
    </div>
  );
}
